INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (3, "nyx_cmn_03", 111031, "", 302, 1, "", "", 13020022, 0.2, "");
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (11, "ふむ…これは僥倖\nかくなる上は再び\n潜航してみるか…", 111031, "", 302, 10, "", "", 13020023, "", "");
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (91, "", 0, "", 302, "", "", "", 13020024, "", "");
