INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (11, "存外意義あるものだ\n資材ダイビングとか\nいう新種の探索行は", 111031, "", 302, 10, "", "", 13020026, "", "");
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (91, 1, 0, "", 302, "", "", "", 13020027, "", "");
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (11, "まあ万一溺れたとて\n後輩たちの誰ぞが\nきっと気付くだろう", 111031, "", 302, 10, "", "", 13020028, "", "");
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (91, 1, 0, "", 302, "", "", "", 13020029, "", "");
