INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (11, "是非もなし\nいざ往かん！", 111031, "", 302, 10, "", "", 13020031, "", "");
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (91, 1, 0, "", 302, "", "", "", 13020032, "", "");
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (93, "", 1.5, "", 302, "", "", "", 13020033, "", "");
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (11, "む。奥に入りすぎた\nこれは…出られぬ！\n誰かー！　誰か―！", 111031, "", 302, 10, "", "", 13020034, "", "");
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (91, "", 0, "", 302, "", "", "", 13020035, "", "");
