INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (11, "ふふふ…我ながら\n納得の出来栄え…", 111031, "", 303, 10, "", "", 13030008, "", "");
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (91, "", 0, "", 303, "", "", "", 13030009, "", "");
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (11, "外観の完成度も\nさることながら\n特筆すべきは機能だ", 111031, "", 303, 10, "", "", 13030010, "", "");
INSERT INTO `v1_85255ec2b65043132c2091154ff2d83ff28ac33ab7f384dfac370e86dfe8fa1f` VALUES (91, "", 0, "", 303, "", "", "", 13030011, "", "");
